"""Exact finite verification for one-pass fair transposition switches on cycles.

No third-party packages required; run: python checker.py
Exhaustive tests are supplementary to the all-length proof.
"""
from collections import Counter
from fractions import Fraction
from itertools import permutations
from math import factorial


def perm_signature(order, mask, k):
    # The cycle edge numbered j joins vertex j to (j+1) modulo k.
    # The action on a tuple of card identities is generated by fair swaps.
    cards = list(range(k))
    for t, edge_index in enumerate(order):
        if (mask >> t) & 1:
            a, b = edge_index, (edge_index + 1) % k
            cards[a], cards[b] = cards[b], cards[a]
    return tuple(cards)


def cyclic_unimodal(order):
    k = len(order)
    rank = [0] * k
    for t, e in enumerate(order):
        rank[e] = t
    extremes = 0
    for e in range(k):
        if ((rank[e] - rank[(e - 1) % k]) *
                (rank[(e + 1) % k] - rank[e]) < 0):
            extremes += 1
    return extremes == 2


def exhaustive(k):
    bad_count = 0
    checks = 0
    for order in permutations(range(k)):
        multiplicity = Counter(perm_signature(order, mask, k)
                               for mask in range(1 << k))
        bad = cyclic_unimodal(order)
        full_mask = (1 << k) - 1
        earliest_omitted = full_mask ^ 1
        latest_omitted = full_mask ^ (1 << (k - 1))
        extremes_omitted = earliest_omitted ^ (1 << (k - 1))
        pair_one = (perm_signature(order, earliest_omitted, k) ==
                    perm_signature(order, latest_omitted, k))
        pair_two = (perm_signature(order, full_mask, k) ==
                    perm_signature(order, extremes_omitted, k))
        assert pair_one == pair_two == bad
        if bad:
            assert (perm_signature(order, full_mask, k) !=
                    perm_signature(order, latest_omitted, k))
            bad_count += 1
            assert len(multiplicity) == (1 << k) - 2
            assert Counter(multiplicity.values()) == {1: (1 << k) - 4, 2: 2}
            # Conditional Shannon information loss in bits (exact rational):
            lost_bits = Fraction(4, 1 << k)
        else:
            assert len(multiplicity) == (1 << k)
            assert set(multiplicity.values()) == {1}
            lost_bits = Fraction(0)
        assert lost_bits == (Fraction(2**(2-k)) if bad else 0)
        checks += 6
    assert bad_count == k * 2 ** (k - 2)
    assert Fraction(bad_count, factorial(k)) == Fraction(2**(k - 2), factorial(k - 1))
    assert (Fraction(bad_count, factorial(k)) * Fraction(4, 1 << k)
            == Fraction(1, factorial(k - 1)))
    checks += 3
    return bad_count, checks


def sampled_long_cycles():
    import random
    rng = random.Random(31043)
    checks = 0
    for k, count in [(9, 80), (10, 35), (11, 10)]:
        for _ in range(count):
            order = list(range(k))
            rng.shuffle(order)
            d = Counter(perm_signature(order, mask, k)
                        for mask in range(1 << k))
            if cyclic_unimodal(order):
                assert Counter(d.values()) == {1: (1 << k) - 4, 2: 2}
            else:
                assert len(d) == 1 << k and set(d.values()) == {1}
            checks += 1
    return checks


def forest_test():
    # Edge lists here are acyclic. Order/bit-word map must be injective.
    families = [
        (4, [(0, 1), (1, 2), (2, 3)]),
        (6, [(0, 1), (0, 2), (1, 3), (1, 4), (4, 5)]),
        (7, [(0, 1), (1, 2), (3, 4), (4, 5), (5, 6)]),
    ]
    assertions = 0
    for n, edges in families:
        for order in permutations(edges):
            seen = set()
            for mask in range(1 << len(order)):
                p = list(range(n))
                for t, (a, b) in enumerate(order):
                    if (mask >> t) & 1:
                        p[a], p[b] = p[b], p[a]
                seen.add(tuple(p))
            assert len(seen) == 1 << len(edges)
            assertions += 1
    return assertions


if __name__ == '__main__':
    total = 0
    for k in range(3, 9):
        bad, checks = exhaustive(k)
        total += checks
        print('cycle', k, 'bad_orders', bad, 'all_orders', factorial(k))
    total += sampled_long_cycles()
    total += forest_test()
    print('PASS assertions across order families:', total)
